ALTER TABLE public.bills ADD COLUMN rf_status text, ADD COLUMN rf_provider text, ADD COLUMN rf_code text, ADD COLUMN story text, ADD COLUMN public_city text, ADD COLUMN confirmation_note text;
ALTER TABLE public.bills ADD CONSTRAINT bills_rf_status_check CHECK (rf_status IS NULL OR rf_status IN ('pending_review','active','pending_verification','paid'));
ALTER TABLE public.bills ADD CONSTRAINT bills_rf_amount_check CHECK (rf_status IS NULL OR (amount > 0 AND amount <= 100 AND amount = round(amount,2)));
ALTER TABLE public.bills ADD CONSTRAINT bills_rf_story_check CHECK (story IS NULL OR char_length(story) <= 140);
GRANT SELECT(rf_status,rf_provider,rf_code,story,public_city) ON public.bills TO anon,authenticated;
DROP POLICY public_open_bills ON public.bills;
CREATE POLICY public_reviewed_rf_bills ON public.bills FOR SELECT TO anon,authenticated USING (rf_status IN ('active','pending_verification','paid') AND NOT is_demo);
CREATE POLICY admin_rf_bills_read ON public.bills FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
GRANT SELECT ON public.bills TO authenticated;
REVOKE SELECT ON public.bills FROM authenticated;
GRANT SELECT(id,provider,amount,due_date,status,is_demo,created_at,demo_remaining,public_description,rf_status,rf_provider,rf_code,story,public_city) ON public.bills TO authenticated;
CREATE TABLE public.bill_submissions (bill_id uuid PRIMARY KEY REFERENCES public.bills(id),owner_id uuid NOT NULL,rf_code text NOT NULL,raw_story text NOT NULL,city text NOT NULL,document_path text NOT NULL,terms_consent boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bill_submissions TO authenticated; GRANT ALL ON public.bill_submissions TO service_role;
ALTER TABLE public.bill_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_owner_admin_read ON public.bill_submissions FOR SELECT TO authenticated USING (owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bill_id uuid NOT NULL REFERENCES public.bills(id),user_id uuid NOT NULL,receipt_image_url text,created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(bill_id));
COMMENT ON COLUMN public.verifications.receipt_image_url IS 'Private storage object path, never a public URL; signed read access only.';
GRANT SELECT ON public.verifications TO authenticated; GRANT ALL ON public.verifications TO service_role;
ALTER TABLE public.verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY verifications_owner_admin_read ON public.verifications FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY rf_document_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='rf-documents' AND (storage.foldername(name))[1]=auth.uid()::text AND (storage.foldername(name))[2] IN ('bills','receipts'));
CREATE POLICY rf_document_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='rf-documents' AND ((storage.foldername(name))[1]=auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.valid_facilitation_rf(code text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE c text; n text=''; r integer=0; i integer; BEGIN IF code !~ '^RF[0-9]{2}[A-Z0-9]{21}$' THEN RETURN false; END IF; FOR i IN 1..char_length(code) LOOP c:=substr(substr(code,5)||substr(code,1,4),i,1); n:=n||CASE WHEN c ~ '[A-Z]' THEN (ascii(c)-55)::text ELSE c END; END LOOP; FOR i IN 1..char_length(n) LOOP r:=(r*10+substr(n,i,1)::integer)%97; END LOOP; RETURN r=1; END $$;
CREATE FUNCTION public.submit_rf_bill(p_provider text,p_amount numeric,p_rf text,p_city text,p_story text,p_due date,p_path text,p_consent boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE bid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; IF p_provider NOT IN ('ΔΕΗ','ΕΥΔΑΠ','Φυσικό Αέριο','Τηλεφωνία') OR p_provider IS NULL OR p_amount IS NULL OR p_amount<=0 OR p_amount>100 OR p_amount<>round(p_amount,2) OR NOT coalesce(public.valid_facilitation_rf(p_rf),false) OR p_city IS NULL OR char_length(trim(p_city)) NOT BETWEEN 2 AND 40 OR p_story IS NULL OR char_length(trim(p_story)) NOT BETWEEN 1 AND 140 OR p_due IS NULL OR p_consent IS DISTINCT FROM true THEN RAISE EXCEPTION 'INVALID_BILL'; END IF;
IF p_path IS NULL OR p_path NOT LIKE auth.uid()::text||'/bills/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='rf-documents' AND name=p_path) THEN RAISE EXCEPTION 'DOCUMENT_REQUIRED'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(p_rf)); IF EXISTS(SELECT 1 FROM public.bill_submissions WHERE rf_code=p_rf) THEN RAISE EXCEPTION 'DUPLICATE_RF'; END IF;
INSERT INTO public.bills(owner_id,provider,first_name,city,note,amount,due_date,status,is_demo,rf_status,rf_provider) VALUES(auth.uid(),CASE WHEN p_provider='Τηλεφωνία' THEN 'Cosmote' ELSE p_provider END,'Private','Private','Private document pending review',p_amount,p_due,'PENDING',false,'pending_review',p_provider) RETURNING id INTO bid;
INSERT INTO public.bill_submissions(bill_id,owner_id,rf_code,raw_story,city,document_path,terms_consent) VALUES(bid,auth.uid(),p_rf,trim(p_story),trim(p_city),p_path,true); RETURN bid; END $$;
CREATE FUNCTION public.claim_rf_payment(p_bill uuid,p_receipt text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE state text; vid uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'SIGN_IN_REQUIRED'; END IF; SELECT rf_status INTO state FROM public.bills WHERE id=p_bill AND NOT is_demo FOR UPDATE; IF state IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'BILL_UNAVAILABLE'; END IF;
IF p_receipt IS NOT NULL AND (p_receipt NOT LIKE auth.uid()::text||'/receipts/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='rf-documents' AND name=p_receipt)) THEN RAISE EXCEPTION 'INVALID_RECEIPT'; END IF;
INSERT INTO public.verifications(bill_id,user_id,receipt_image_url) VALUES(p_bill,auth.uid(),p_receipt) RETURNING id INTO vid; UPDATE public.bills SET rf_status='pending_verification' WHERE id=p_bill; RETURN vid; END $$;
CREATE FUNCTION public.review_rf_bill(p_bill uuid,p_action text,p_story text DEFAULT NULL,p_city text DEFAULT NULL,p_note text DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bills; s public.bill_submissions; BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'FORBIDDEN'; END IF; SELECT * INTO b FROM public.bills WHERE id=p_bill AND NOT is_demo FOR UPDATE;
IF p_action='approve' AND b.rf_status='pending_review' THEN IF p_story IS NULL OR char_length(trim(p_story)) NOT BETWEEN 1 AND 140 OR p_city IS NULL OR char_length(trim(p_city)) NOT BETWEEN 2 AND 40 THEN RAISE EXCEPTION 'REDACTED_DETAILS_REQUIRED'; END IF; SELECT * INTO s FROM public.bill_submissions WHERE bill_id=p_bill; IF NOT public.valid_facilitation_rf(s.rf_code) THEN RAISE EXCEPTION 'INVALID_RF'; END IF; UPDATE public.bills SET rf_status='active',rf_code=s.rf_code,story=trim(p_story),public_city=trim(p_city) WHERE id=p_bill;
ELSIF p_action='paid' AND b.rf_status='pending_verification' THEN IF p_note IS NULL OR char_length(trim(p_note)) NOT BETWEEN 10 AND 500 THEN RAISE EXCEPTION 'INDEPENDENT_CONFIRMATION_REQUIRED'; END IF; UPDATE public.bills SET rf_status='paid',confirmation_note=trim(p_note) WHERE id=p_bill;
ELSE RAISE EXCEPTION 'INVALID_TRANSITION'; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.submit_rf_bill(text,numeric,text,text,text,date,text,boolean),public.claim_rf_payment(uuid,text),public.review_rf_bill(uuid,text,text,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.submit_rf_bill(text,numeric,text,text,text,date,text,boolean),public.claim_rf_payment(uuid,text),public.review_rf_bill(uuid,text,text,text,text) TO authenticated;
REVOKE EXECUTE ON FUNCTION public.record_demo_wipe(uuid,numeric,uuid) FROM authenticated,anon,PUBLIC;
CREATE INDEX bills_rf_status_idx ON public.bills(rf_status,created_at);
COMMENT ON COLUMN public.bills.demo_remaining IS 'DEPRECATED for current RF workflow; historical simulation data only.';
COMMENT ON TABLE public.wipes IS 'DEPRECATED for new contributions; historical simulations retained.';